#define PINYIN_COUNT (sizeof(g_pinyin_table) / sizeof(g_pinyin_table[0]))
#define HANZI_COUNT (sizeof(g_hanzi_table) / sizeof(g_hanzi_table[0]))

/* ===================== 查找算法 ===================== */

/**
 * @brief 拼音转候选汉字（完全匹配，忽略音调）
 * @param pinyin            输入拼音（无音调数字），如 "di"
 * @param hanzi_candidates  输出缓冲区，写入 UTF-32 码点
 * @return 候选汉字数量
 *
 * @note 调用者需保证 hanzi_candidates 至少有 HANZI_COUNT 个元素。
 * @note 返回的候选字已按字频降序预排列，无需运行时排序。
 */
size_t pinyin_to_hanzi(char *pinyin, uint32_t *hanzi_candidates) {
    size_t left = 0, right = PINYIN_COUNT;
    size_t mid;
    int cmp;

    /* 二分查找完全匹配的拼音 */
    while (left < right) {
        mid = left + (right - left) / 2;
        cmp = strcmp(g_pinyin_table[mid].pinyin, pinyin);
        if (cmp < 0) {
            left = mid + 1;
        } else if (cmp > 0) {
            right = mid;
        } else {
            /* 找到完全匹配，直接复制预排序的候选字 */
            int i;
            for (i = 0; i < g_pinyin_table[mid].hanzi_count; i++) {
                hanzi_candidates[i] = g_hanzi_table[g_pinyin_table[mid].hanzi_indices[i]];
            }
            return g_pinyin_table[mid].hanzi_count;
        }
    }
    return 0;  /* 未找到 */
}

/* ===================== 测试代码 ===================== */
#ifdef PINYIN_TEST_MAIN
#include <stdio.h>

/* 将 UTF-32 码点转为 UTF-8 字节序列并输出，不依赖 locale */
static void print_utf32_char(uint32_t cp) {
    char buf[5] = {0};
    if (cp <= 0x7F) {
        buf[0] = (char)cp;
    } else if (cp <= 0x7FF) {
        buf[0] = (char)(0xC0 | (cp >> 6));
        buf[1] = (char)(0x80 | (cp & 0x3F));
    } else if (cp <= 0xFFFF) {
        buf[0] = (char)(0xE0 | (cp >> 12));
        buf[1] = (char)(0x80 | ((cp >> 6) & 0x3F));
        buf[2] = (char)(0x80 | (cp & 0x3F));
    } else {
        buf[0] = (char)(0xF0 | (cp >> 18));
        buf[1] = (char)(0x80 | ((cp >> 12) & 0x3F));
        buf[2] = (char)(0x80 | ((cp >> 6) & 0x3F));
        buf[3] = (char)(0x80 | (cp & 0x3F));
    }
    printf("%s", buf);
}

int main(int argc, char *argv[]) {
    uint32_t candidates[HANZI_COUNT];
    const char *tests[] = {"de", "zhi", "li", "ji", "yi", "xyz"};
    size_t n_tests = sizeof(tests) / sizeof(tests[0]);
    size_t t, i, n;
    (void)argc; (void)argv;

    for (t = 0; t < n_tests; t++) {
        n = pinyin_to_hanzi((char*)tests[t], candidates);
        printf("pinyin: %-6s -> %lu candidates: ",
               tests[t], (unsigned long)n);
        for (i = 0; i < n; i++) {
            printf("U+%04X(", candidates[i]);
            print_utf32_char(candidates[i]);
            printf(") ");
        }
        printf("\n");
    }
    return 0;
}
#endif